using System;using System.IO;using System.Linq;using System.Text.RegularExpressions;
static class WidgetBackup {
 static bool OwnedDirectory(string path){return Directory.Exists(path)&&(File.GetAttributes(path)&FileAttributes.ReparsePoint)==0;}
 static void CopyFiles(string source,string destination,string[] names){if(!OwnedDirectory(source))return;foreach(string name in names){string file=Path.Combine(source,name);if(!File.Exists(file)||(File.GetAttributes(file)&FileAttributes.ReparsePoint)!=0)continue;Directory.CreateDirectory(destination);File.Copy(file,Path.Combine(destination,name),true);}}
 // Credentials and the widget's own data are small. Runtime/plugin caches stay in place.
 public static void Create(string data,string backup){Directory.CreateDirectory(backup);CopyFiles(data,backup,new[]{"settings.json","settings.json.bak","accounts.json","accounts.json.bak","connection-mode.txt","status.json","status.json.bak"});string[] credentials={"auth.json","auth.json.bak","config.toml"};CopyFiles(Path.Combine(data,"account"),Path.Combine(backup,"account"),credentials);string accounts=Path.Combine(data,"accounts");if(OwnedDirectory(accounts))foreach(string dir in Directory.GetDirectories(accounts)){string name=Path.GetFileName(dir);if(Regex.IsMatch(name,"^[a-z0-9-]{1,40}$"))CopyFiles(dir,Path.Combine(backup,"accounts",name),credentials);}string cache=Path.Combine(data,"cache");if(OwnedDirectory(cache)){string[] names=Directory.GetFiles(cache).Select(Path.GetFileName).Where(n=>Regex.IsMatch(n,"^[a-z0-9-]{1,40}\\.json(\\.bak)?$")).ToArray();CopyFiles(cache,Path.Combine(backup,"cache"),names);}}
}
